namespace sv_2e95b646e17644e9bceb79ea95cf5d67.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_2e95b646e17644e9bceb79ea95cf5d67.Models;

namespace sv_2e95b646e17644e9bceb79ea95cf5d67.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000);
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(300);
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@* Step indicator bar showing progress through the multi-step form *@

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = stepIndex < CurrentStep;
            var isCurrent = stepIndex == CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <div class="text-center flex-fill position-relative">
                <button type="button"
                        class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepCircleClass(stepIndex)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@isFuture"
                        @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isCurrent ? "fw-bold" : "") @(isFuture ? "text-muted" : "")">
                    @StepNames[stepIndex]
                </div>
            </div>
        }
    </div>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string StepCircleClass(int step)
    {
        if (step < CurrentStep) return "btn-success text-white";
        if (step == CurrentStep) return "btn-primary text-white";
        return "btn-outline-secondary";
    }
}

