<div class="d-flex justify-content-end mt-4">
    <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating...</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private HashSet<string> Errors = new();
    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        Errors.Clear();
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName)) Errors.Add("FullName");
        if (string.IsNullOrWhiteSpace(Email)) Errors.Add("Email");
        if (string.IsNullOrWhiteSpace(Phone)) Errors.Add("Phone");
        if (string.IsNullOrWhiteSpace(Address)) Errors.Add("Address");

        if (Errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                Errors.Add("Email");
                ErrorMessage = "The email address could not be validated. Please check it and try again.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

