@using sv_2e95b646e17644e9bceb79ea95cf5d67.Models

<h4 class="mb-3">Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control @(Errors.Contains("FullName") ? "is-invalid" : "")"
               value="@FullName"
               @onchange="e => FullName = e.Value?.ToString() ?? "" " />
        @if (Errors.Contains("FullName"))
        {
            <div class="invalid-feedback">Full name is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email" class="form-control @(Errors.Contains("Email") ? "is-invalid" : "")"
               value="@Email"
               @onchange="e => Email = e.Value?.ToString() ?? "" " />
        @if (Errors.Contains("Email"))
        {
            <div class="invalid-feedback">A valid email is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control @(Errors.Contains("Phone") ? "is-invalid" : "")"
               value="@Phone"
               @onchange="e => Phone = e.Value?.ToString() ?? "" " />
        @if (Errors.Contains("Phone"))
        {
            <div class="invalid-feedback">Phone number is required.</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input type="text" class="form-control @(Errors.Contains("Address") ? "is-invalid" : "")"
               value="@Address"
               @onchange="e => Address = e.Value?.ToString() ?? "" " />
        @if (Errors.Contains("Address"))
        {
            <div class="invalid-feedback">Address is required.</div>
        }
    </div>
</div>

<div class="d-flex justify-content-end mt-4">
    <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating...</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private HashSet<string> Errors = new();
    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        Errors.Clear();
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName)) Errors.Add("FullName");
        if (string.IsNullOrWhiteSpace(Email)) Errors.Add("Email");
        if (string.IsNullOrWhiteSpace(Phone)) Errors.Add("Phone");
        if (string.IsNullOrWhiteSpace(Address)) Errors.Add("Address");

        if (Errors.Count > 0) return;

        if (ValidateEmail is not null)
        {
            IsValidating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Email);
            IsValidating = false;

            if (!isValid)
            {
                Errors.Add("Email");
                ErrorMessage = "The email address could not be validated. Please check it and try again.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName, Email, Phone, Address));
    }
}

