@page "/apply"
@using sv_2e95b646e17644e9bceb79ea95cf5d67.Models
@using sv_2e95b646e17644e9bceb79ea95cf5d67.Components.JobApplication
@rendermode InteractiveServer

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep"
                   StepNames="@_stepNames"
                   OnStepClicked="GoToStep" />

    <div class="mt-4">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalInfoNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="@_workEntries"
                                 OnNext="HandleWorkHistoryNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="@_references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="@_coverLetter"
                                 MaxLength="2000"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="@_workEntries"
                            References="@_references"
                            CoverLetter="@_coverLetter"
                            OnEditStep="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private static readonly IReadOnlyList<string> _stepNames = new[]
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private int _currentStep;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkEntry> _workEntries = new() { new("", "", DateTime.Today, null, "") };

    // Step 3 state
    private List<Reference> _references = new() { new("", "", "", "") };

    // Step 4 state
    private string _coverLetter = "";

    private PersonalInfo GetPersonalInfo() => new(_fullName, _email, _phone, _address);

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _currentStep = step;
        }
    }

    private void GoBack()
    {
        if (_currentStep > 0) _currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfo info)
    {
        _fullName = info.FullName;
        _email = info.Email;
        _phone = info.Phone;
        _address = info.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntry> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            GetPersonalInfo(),
            new WorkHistory(_workEntries),
            _references,
            _coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

